  async checkPermission() {
    const enabled = await firebase.messaging().hasPermission();
    if (enabled) {
      //ToastAndroid.show('permission enabled', ToastAndroid.SHORT);
      this.getToken();
    } else {
      this.requestPermission();
      //ToastAndroid.show('permission disabled', ToastAndroid.SHORT);
    }
  }

  async getToken() {
    let fcmToken = await AsyncStorage.getItem('fcmToken');
    
    axios.post('https://classcast-198812.appspot.com/token/save_fcm_token/', {
     username: this.state.username,
     fcmToken: fcmToken
    });

    if (!fcmToken) {
      fcmToken = await firebase.messaging().getToken();
      if (fcmToken) {
        //ToastAndroid.show('permission granted', ToastAndroid.SHORT);
        await AsyncStorage.setItem('fcmToken', fcmToken);
      }
    }
  }

  async requestPermission() {
    try {
      await firebase.messaging().requestPermission();
      // User has authorised
      this.getToken();
    } catch (error) {
      // User has rejected permissions
      console.log('permission rejected');
    }
  }

  async createNotificationListeners() {
    /*
    * Triggered when a particular notification has been received in foreground
    * */
    this.notificationListener = firebase.notifications().onNotification((notification) => {
        const { title, body } = notification;
        const action = notification.data;
        console.log("scmsnls: "+JSON.stringify(action));
        this.showAlert(title, body);
        this.buildNotification(notification);
        
    });

    /*
    * If your app is in background, you can listen for when a notification is clicked / tapped / opened as follows:
    * */
    this.notificationOpenedListener = firebase.notifications().onNotificationOpened((notificationOpen) => {
        const { title, body } = notificationOpen.notification;
        this.showAlert(title, body);
    });

    /*
    * If your app is closed, you can check if it was opened by a notification being clicked / tapped / opened as follows:
    * */
    const notificationOpen = await firebase.notifications().getInitialNotification();
    if (notificationOpen) {
        const { title, body } = notificationOpen.notification;
        const action = notificationOpen.notification.data;
        console.log("dsamsadlm: "+JSON.stringify(notificationOpen.notification.data));
        if(notificationOpen.notification.data.type == 'pdf') {
          const navigateAction = NavigationActions.navigate({
            routeName: 'pdfViewer',
            params: {
              url: notificationOpen.notification.data.url
            },
          });
          this.props.navigation.dispatch(navigateAction);
        }
        //this.showAlert(title, body);
    }
    /*
    * Triggered for data only payload in foreground
    * */
    this.messageListener = firebase.messaging().onMessage((message) => {
      //process data message
      console.log(JSON.stringify(message));
    });
  }

